use rhwp::{DocumentCore,model::{document::Document,paragraph::{Paragraph,CharShapeRef},control::{Control,UnknownControl,Bookmark,Hyperlink,FieldType},header_footer::{Header,Footer,MasterPage},shape::Caption,table::{Table,Cell}},serializer::{serialize_hwpx_with_report,serialize_hwp_with_report,ContentLossCode,ContentLossSubject,ContentLossReason}};
use sha2::{Sha256,Digest};
use std::path::PathBuf;
fn hash(b:&[u8])->String {Sha256::digest(b).iter().map(|v|format!("{v:02x}")).collect()}
fn model_bytes(d:&Document)->Vec<u8>{format!("{d:?}").into_bytes()}
fn para(text:&str,unknown:bool)->Paragraph {let mut p=Paragraph{text:text.into(),char_count:text.encode_utf16().count() as u32+1,char_shapes:vec![CharShapeRef{start_pos:0,char_shape_id:0}],char_offsets:(0..text.encode_utf16().count() as u32).collect(),..Default::default()};if unknown{p.controls.push(Control::Unknown(UnknownControl{ctrl_id:0x11223344}));}p}
fn table(p:Paragraph)->Table {let mut t=Table{row_count:1,col_count:1,row_sizes:vec![1],cells:vec![Cell{paragraphs:vec![p],width:14000,height:2000,col_span:1,row_span:1,..Default::default()}],..Default::default()};t.common.width=14000;t.common.height=2000;t.rebuild_grid();t}
fn fixture(mode:&str,unknown:bool)->(Document,String) {let mut c=DocumentCore::new_empty();c.create_blank_document_native().unwrap();let mut d=c.document().clone();d.sections[0].raw_stream=None;let root=&mut d.sections[0].paragraphs[0];*root=para("OWN UNKNOWN LOSS SOURCE",false);let path=match mode{
"body"=>{root.controls=para("",unknown).controls;"section/0/body/paragraph/0/control/0".into()},
"nested-cell"=>{let nested=table(para("OWN INNER CELL",unknown));root.controls.push(Control::Table(Box::new(table(Paragraph{controls:vec![Control::Table(Box::new(nested))],..para("OWN OUTER CELL",false)}))));"section/0/body/paragraph/0/control/0/cell/0/paragraph/0/control/0/cell/0/paragraph/0/control/0".into()},
"header"=>{root.controls.push(Control::Header(Box::new(Header{paragraphs:vec![para("OWN HEADER",unknown)],..Default::default()})));"section/0/body/paragraph/0/control/0/header/paragraph/0/control/0".into()},
"footer"=>{root.controls.push(Control::Footer(Box::new(Footer{paragraphs:vec![para("OWN FOOTER",unknown)],..Default::default()})));"section/0/body/paragraph/0/control/0/footer/paragraph/0/control/0".into()},
"caption"=>{let mut t=table(para("OWN CELL",false));t.caption=Some(Caption{paragraphs:vec![para("OWN CAPTION",unknown)],..Default::default()});root.controls.push(Control::Table(Box::new(t)));"section/0/body/paragraph/0/control/0/caption/paragraph/0/control/0".into()},
"master"=>{d.sections[0].section_def.master_pages.push(MasterPage{paragraphs:vec![para("OWN MASTER",unknown)],..Default::default()});"section/0/master/0/paragraph/0/control/0".into()},_=>panic!("unknown fixture")};let r=&mut d.sections[0].paragraphs[0];let slots=r.controls.len() as u32*8;r.char_count+=slots;for x in &mut r.char_offsets{*x+=slots;}(d,path)}
fn save_observation(name:&str,value:serde_json::Value){let dir=PathBuf::from(std::env::var("JUEONY_TEST_OUTPUT").expect("own absolute output"));std::fs::create_dir_all(&dir).unwrap();std::fs::write(dir.join(format!("{name}.json")),serde_json::to_vec_pretty(&value).unwrap()).unwrap();}
fn check_unknown(mode:&str){let(d,path)=fixture(mode,true);let before=model_bytes(&d);let hwp=serialize_hwp_with_report(&d).unwrap();assert!(hwp.content_loss().is_empty(),"HWP reporting must not change");let a=serialize_hwpx_with_report(&d).unwrap();let report=a.content_loss();assert_eq!(serialize_hwp_with_report(&d).unwrap().bytes(),hwp.bytes(),"HWP bytes changed after reporting");assert_eq!(model_bytes(&d),before,"writer mutated source");save_observation(mode,serde_json::json!({"mode":mode,"sourceSha256":hash(&before),"sourceUnchanged":true,"hwpSha256":hash(hwp.bytes()),"hwpxSha256":hash(a.bytes()),"expectedPath":path,"report":serde_json::from_str::<serde_json::Value>(&report.to_json()).unwrap()}));assert_eq!(report.len(),1,"unknown must have exactly one loss, {mode}");let l=&report.losses()[0];assert_eq!(l.path,path);assert_eq!(l.code,ContentLossCode::ControlOmitted);assert_eq!(l.subject,ContentLossSubject::Control);assert_eq!(l.reason,ContentLossReason::UnsupportedByOutputFormat);assert_eq!(l.resource_id,None);let second=serialize_hwpx_with_report(&d).unwrap();assert_eq!(a.bytes(),second.bytes());assert_eq!(report,second.content_loss());}
#[test]fn unknown_body(){check_unknown("body")}
#[test]fn unknown_nested_cell(){check_unknown("nested-cell")}
#[test]fn unknown_header(){check_unknown("header")}
#[test]fn unknown_footer(){check_unknown("footer")}
#[test]fn unknown_caption(){check_unknown("caption")}
#[test]fn unknown_master(){check_unknown("master")}
#[test]fn known_containers_have_no_false_loss(){for mode in["body","nested-cell","header","footer","caption","master"]{let(mut d,_)=fixture(mode,false);d.sections[0].paragraphs[0].controls.push(Control::Bookmark(Bookmark{name:"OWN-KNOWN-BOOKMARK".into()}));d.sections[0].paragraphs[0].char_count+=8;for x in &mut d.sections[0].paragraphs[0].char_offsets{*x+=8;}let before=model_bytes(&d);for a in[serialize_hwpx_with_report(&d).unwrap(),serialize_hwp_with_report(&d).unwrap()]{assert!(a.content_loss().is_empty(),"known {mode}: {}",a.content_loss().to_json());assert_eq!(model_bytes(&d),before);let reopened=DocumentCore::from_bytes(a.bytes()).unwrap();assert!(reopened.document().sections[0].paragraphs[0].text.contains("OWN UNKNOWN LOSS SOURCE"),"known mode={mode} format={:?} reopened={:?}",a.content_loss().output_format(),reopened.document().sections[0].paragraphs[0].text);}}}
#[test]fn native_core_report_owns_the_same_body_loss(){let(d,path)=fixture("body",true);let mut core=DocumentCore::new_empty();core.set_document(d);let before=model_bytes(core.document());let a=core.export_hwpx_native_with_report().unwrap();save_observation("native-core",serde_json::json!({"expectedPath":path,"report":serde_json::from_str::<serde_json::Value>(&a.content_loss().to_json()).unwrap(),"sourceSha256":hash(&before),"bytesSha256":hash(a.bytes())}));assert_eq!(model_bytes(core.document()),before);assert_eq!(a.content_loss().len(),1);assert_eq!(a.content_loss().losses()[0].path,path);}
#[test]fn unknown_zero_identifier_still_reports_unsupported_hwpx_control(){let(mut d,path)=fixture("body",true);d.sections[0].paragraphs[0].controls[0]=Control::Unknown(UnknownControl{ctrl_id:0});let a=serialize_hwpx_with_report(&d).unwrap();assert_eq!(a.content_loss().len(),1);assert_eq!(a.content_loss().losses()[0].path,path);assert!(serialize_hwp_with_report(&d).unwrap().content_loss().is_empty());}

#[test]fn parsed_hwp_original_unknown_control_receives_report(){let path="/mnt/c/Users/jjome/Documents/work/jueony/build/file-closure69-overlap/support/negative.hwp";let bytes=std::fs::read(path).unwrap();assert_eq!(hash(&bytes),"a5c62e0b6cff7a9ba3445517bfc2f47494f841d75694f45400911fb115c3eec8");let original=DocumentCore::from_bytes(&bytes).unwrap();let original_model=model_bytes(original.document());let mut doc=original.document().clone();let index=doc.sections[0].paragraphs[2].controls.len();doc.sections[0].paragraphs[2].controls.push(Control::Unknown(UnknownControl{ctrl_id:0x11223344}));let mut core=DocumentCore::new_empty();core.set_document(doc);let before=model_bytes(core.document());let a=core.export_hwpx_native_with_report().unwrap();let expected=format!("section/0/body/paragraph/2/control/{index}");save_observation("actual-parsed-hwp",serde_json::json!({"sourceBytesSha256":hash(&bytes),"originalModelSha256":hash(&original_model),"mutatedSourceSha256":hash(&before),"expectedPath":expected,"report":serde_json::from_str::<serde_json::Value>(&a.content_loss().to_json()).unwrap(),"outputSha256":hash(a.bytes())}));assert_eq!(model_bytes(original.document()),original_model);assert_eq!(model_bytes(core.document()),before);assert_eq!(std::fs::read(path).unwrap(),bytes);assert_eq!(a.content_loss().len(),1);let l=&a.content_loss().losses()[0];assert_eq!(l.path,expected);assert_eq!(l.code,ContentLossCode::ControlOmitted);assert_eq!(l.subject,ContentLossSubject::Control);assert_eq!(l.reason,ContentLossReason::UnsupportedByOutputFormat);}

#[test]fn supported_hyperlink_is_not_false_loss_and_private_url_never_enters_loss_report(){let(mut d,_)=fixture("body",false);let url="https://example.invalid/OWN-PRIVATE-URL-DO-NOT-REPORT";d.sections[0].paragraphs[0].controls.push(Control::Hyperlink(Hyperlink{url:url.into(),text:"OWN-LINK-LABEL".into()}));let before=model_bytes(&d);let a=serialize_hwpx_with_report(&d).unwrap();assert!(a.content_loss().is_empty());assert!(!a.content_loss().to_json().contains(url));let reopened=DocumentCore::from_bytes(a.bytes()).unwrap();assert!(reopened.document().sections[0].paragraphs[0].controls.iter().any(|c|matches!(c,Control::Field(f) if f.field_type==FieldType::Hyperlink&&f.command==url)));assert!(serialize_hwp_with_report(&d).unwrap().content_loss().is_empty());assert_eq!(model_bytes(&d),before);d.sections[0].paragraphs[0].controls.push(Control::Unknown(UnknownControl{ctrl_id:0x11223344}));let mixed=serialize_hwpx_with_report(&d).unwrap();let report=mixed.content_loss().to_json();save_observation("hyperlink-negative",serde_json::json!({"supportedHyperlinkPreserved":true,"urlNotInReport":!report.contains(url),"mixedReport":serde_json::from_str::<serde_json::Value>(&report).unwrap()}));assert_eq!(mixed.content_loss().len(),1);assert_eq!(mixed.content_loss().losses()[0].path,"section/0/body/paragraph/0/control/1");assert!(!report.contains(url));assert!(!report.contains("OWN-LINK-LABEL"));}
